// ===== Analyze Signals: SMA 50/200 + RSI 14 + deteksi sinyal =====
const sma = (arr, p) =>
  arr.length < p ? null : arr.slice(-p).reduce((a, b) => a + b, 0) / p;

// RSI 14 (Wilder smoothing)
function rsi(closes, period = 14) {
  if (closes.length < period + 1) return null;
  let gain = 0, loss = 0;
  for (let i = 1; i <= period; i++) {
    const d = closes[i] - closes[i - 1];
    if (d >= 0) gain += d; else loss -= d;
  }
  let avgGain = gain / period, avgLoss = loss / period;
  for (let i = period + 1; i < closes.length; i++) {
    const d = closes[i] - closes[i - 1];
    avgGain = (avgGain * (period - 1) + (d > 0 ? d : 0)) / period;
    avgLoss = (avgLoss * (period - 1) + (d < 0 ? -d : 0)) / period;
  }
  if (avgLoss === 0) return 100;
  return 100 - 100 / (1 + avgGain / avgLoss);
}

const round = (v) => (v === null ? null : Math.round(v * 100) / 100);
const results = [];

for (const item of $input.all()) {
  const r = item.json.chart?.result?.[0];
  if (!r) continue;

  const symbol = r.meta.symbol;
  const closes = (r.indicators.quote[0].close || []).filter((c) => c !== null && c !== undefined);
  if (closes.length < 15) continue;

  const lastClose = closes[closes.length - 1];
  const ma50 = sma(closes, 50);
  const ma200 = sma(closes, 200);
  const prev = closes.slice(0, -1);
  const ma50Prev = sma(prev, 50);
  const ma200Prev = sma(prev, 200);
  const rsiVal = rsi(closes, 14);

  const signals = [];
  if (rsiVal !== null && rsiVal < 30) signals.push('🟢 RSI Oversold (< 30) - potensi beli');
  if (rsiVal !== null && rsiVal > 70) signals.push('🔴 RSI Overbought (> 70) - potensi jual');

  let trend = 'MA200 belum tersedia (data kurang)';
  if (ma50 !== null && ma200 !== null) {
    trend = ma50 > ma200 ? 'Bullish (MA50 > MA200)' : 'Bearish (MA50 < MA200)';
    if (ma50Prev !== null && ma200Prev !== null) {
      if (ma50Prev <= ma200Prev && ma50 > ma200) signals.push('🟢 Golden Cross (MA50 menembus MA200 ke atas)');
      if (ma50Prev >= ma200Prev && ma50 < ma200) signals.push('🔴 Death Cross (MA50 menembus MA200 ke bawah)');
    }
  }

  results.push({
    json: {
      symbol,
      lastClose: round(lastClose),
      rsi: round(rsiVal),
      ma50: round(ma50),
      ma200: round(ma200),
      trend,
      signal: signals.length ? signals.join('\n') : '⚪ Tidak ada sinyal saat ini',
    },
  });
}
return results;

